use std::collections::BTreeMap;
use std::io::{self, Read, Write};

struct Account {
    balance: u64,
    journal: Vec<String>,
}

struct Out {
    buf: String,
    error: bool,
}

impl Out {
    fn line(&mut self, s: impl AsRef<str>) {
        let s = s.as_ref();
        if s.starts_with("error:") {
            self.error = true;
        }
        self.buf.push_str(s);
        self.buf.push('\n');
    }
}

const BAD: &str = "error: bad command";

fn parse_amount(s: &str) -> Option<u64> {
    if s.is_empty() || s.len() > 9 || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse().ok()
}

// Callers must have checked that both accounts exist and that funds suffice.
fn move_funds(accounts: &mut BTreeMap<String, Account>, from: &str, to: &str, amt: u64) {
    let src = accounts.get_mut(from).unwrap();
    src.balance -= amt;
    src.journal.push(format!("out {} to {}", amt, to));
    let dst = accounts.get_mut(to).unwrap();
    dst.balance += amt;
    dst.journal.push(format!("in {} from {}", amt, from));
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut out = Out {
        buf: String::new(),
        error: false,
    };
    let mut accounts: BTreeMap<String, Account> = BTreeMap::new();
    let mut ious: Vec<(String, String, u64)> = Vec::new();

    for line in input.lines() {
        if line.is_empty() {
            continue;
        }
        let f: Vec<&str> = line.split(' ').collect();
        match f.as_slice() {
            ["open", name, amt] => {
                let name = *name;
                match parse_amount(amt) {
                    None => out.line(BAD),
                    Some(_) if accounts.contains_key(name) => {
                        out.line(format!("error: account exists {}", name))
                    }
                    Some(v) => {
                        accounts.insert(
                            name.to_string(),
                            Account {
                                balance: v,
                                journal: vec![format!("open {}", v)],
                            },
                        );
                    }
                }
            }
            ["transfer", from, to, amt] => {
                let (from, to) = (*from, *to);
                match parse_amount(amt) {
                    Some(v) if v >= 1 => {
                        if !accounts.contains_key(from) {
                            out.line(format!("error: unknown account {}", from));
                        } else if !accounts.contains_key(to) {
                            out.line(format!("error: unknown account {}", to));
                        } else if from == to {
                            out.line("error: self transfer");
                        } else if accounts[from].balance < v {
                            out.line(format!("error: overdraft {}", from));
                        } else {
                            move_funds(&mut accounts, from, to, v);
                        }
                    }
                    _ => out.line(BAD),
                }
            }
            ["iou", debtor, creditor, amt] => {
                let (d, c) = (*debtor, *creditor);
                match parse_amount(amt) {
                    Some(v) if v >= 1 => {
                        if !accounts.contains_key(d) {
                            out.line(format!("error: unknown account {}", d));
                        } else if !accounts.contains_key(c) {
                            out.line(format!("error: unknown account {}", c));
                        } else if d == c {
                            out.line("error: self transfer");
                        } else {
                            ious.push((d.to_string(), c.to_string(), v));
                        }
                    }
                    _ => out.line(BAD),
                }
            }
            ["balance", name] => match accounts.get(*name) {
                Some(a) => out.line(format!("{}: {}", name, a.balance)),
                None => out.line(format!("error: unknown account {}", name)),
            },
            ["all"] => {
                if accounts.is_empty() {
                    out.line("(no accounts)");
                }
                for (name, a) in &accounts {
                    out.line(format!("{}: {}", name, a.balance));
                }
            }
            ["history", name] => match accounts.get(*name) {
                Some(a) => {
                    for e in &a.journal {
                        out.line(e);
                    }
                }
                None => out.line(format!("error: unknown account {}", name)),
            },
            ["settle"] => {
                let book = std::mem::take(&mut ious);
                let mut net: BTreeMap<String, i64> = BTreeMap::new();
                for (d, c, v) in &book {
                    *net.entry(d.clone()).or_insert(0) -= *v as i64;
                    *net.entry(c.clone()).or_insert(0) += *v as i64;
                }

                let mut steps = 0;
                loop {
                    // Largest debt; ties go to the smallest name (BTreeMap iterates ascending).
                    let mut debtor: Option<(String, i64)> = None;
                    for (n, &p) in &net {
                        if p < 0 && debtor.as_ref().map_or(true, |(_, best)| p < *best) {
                            debtor = Some((n.clone(), p));
                        }
                    }
                    // Largest credit; ties go to the smallest name.
                    let mut creditor: Option<(String, i64)> = None;
                    for (n, &p) in &net {
                        if p > 0 && creditor.as_ref().map_or(true, |(_, best)| p > *best) {
                            creditor = Some((n.clone(), p));
                        }
                    }
                    let (d, dp, c, cp) = match (debtor, creditor) {
                        (Some((d, dp)), Some((c, cp))) => (d, dp, c, cp),
                        _ => break,
                    };

                    let amt = (-dp).min(cp);
                    *net.get_mut(&d).unwrap() += amt;
                    *net.get_mut(&c).unwrap() -= amt;
                    let amt = amt as u64;
                    steps += 1;

                    let funded = accounts[d.as_str()].balance >= amt;
                    let suffix = if funded { "" } else { " (failed: overdraft)" };
                    out.line(format!("{} pays {} {}{}", d, c, amt, suffix));
                    if funded {
                        move_funds(&mut accounts, &d, &c, amt);
                    }
                }
                if steps == 0 {
                    out.line("nothing to settle");
                }
            }
            _ => out.line(BAD),
        }
    }

    let mut stdout = io::stdout();
    stdout.write_all(out.buf.as_bytes()).unwrap();
    stdout.flush().unwrap();
    if out.error {
        std::process::exit(1);
    }
}
